// CommuLingo guided reading (format 'guided-reading'): each lesson shows a
// passage of the site's full translation first, then one question on it, with
// four choices (as in the Engels Ludwig Feuerbach course). Korean passages are
// verbatim from the document lenin-imperialism-1916 (scripts/check-course-source-excerpts.js
// checks them and their anchors). Lenin wrote the book in Russian, so the English
// passages are translated here from the Russian text the document carries.
// A passage may skip text with ' … '.
// Rewritten 2026-10-31 from the earlier quiz course: chapter ids stay
// (imperialism-chNN) so chapter links keep working. Every question is new, so the
// lessons take new ids (imperialism-chNN-reading) and the old quiz lessons'
// answer history is not counted for the new questions.

function t(ko, en) {
    return { ko, en };
}

const DOC = '/commulingo/docs/lenin-imperialism-1916';
const FROM_RUSSIAN = ' (our translation from the Russian)';
const TITLE_KO = '『자본주의의 최고 단계로서의 제국주의』';
const TITLE_EN = 'Imperialism, the Highest Stage of Capitalism';
const ROMAN = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'];

const LABELS = {
    'preface-1917': t('레닌, 1917년 서문', 'Lenin, preface of 1917' + FROM_RUSSIAN),
    'preface-1920': t('레닌, 1920년 프랑스어판·독일어판 서문', 'Lenin, preface to the French and German editions (1920)' + FROM_RUSSIAN),
    introduction: t(`${TITLE_KO} 머리말`, `${TITLE_EN}, introduction` + FROM_RUSSIAN),
};
ROMAN.forEach(r => {
    LABELS[`chapter-${r.toLowerCase()}`] = t(`${TITLE_KO} ${r}장`, `${TITLE_EN}, chapter ${r}` + FROM_RUSSIAN);
});

function passage(anchor, contextKo, contextEn, quoteKo, quoteEn) {
    return {
        context: t(contextKo, contextEn),
        source: { href: `${DOC}#${anchor}`, label: LABELS[anchor], quote: t(quoteKo, quoteEn) },
    };
}

// Choices and their feedback are authored correct answer first, which is how
// they are stored (answer 0); the player shuffles them for display.
function q(where, koPrompt, enPrompt, koChoices, enChoices, koExplanation, enExplanation, koFeedback, enFeedback) {
    return {
        type: 'multiple_choice',
        points: 0,
        context: where.context,
        prompt: t(koPrompt, enPrompt),
        choices: { ko: koChoices, en: enChoices },
        answer: 0,
        explanation: t(koExplanation, enExplanation),
        choiceFeedback: { ko: koFeedback, en: enFeedback },
        source: where.source,
    };
}

function chapter(ch, anchor, titleKo, titleEn, summaryKo, summaryEn, questions) {
    const id = `imperialism-ch${String(ch).padStart(2, '0')}`;
    return {
        id,
        volumeNumber: 4,
        chapterNumber: ch,
        title: t(titleKo, titleEn),
        sourceUrl: `${DOC}#${anchor}`,
        summary: t(summaryKo, summaryEn),
        lessons: [{
            id: `${id}-reading`,
            level: 'basic',
            title: t(titleKo, titleEn),
            questions: questions.map((item, index) => ({ ...item, id: `q${index + 1}`, points: 2 })),
        }],
    };
}

